// Pano Gecmisi: kopyalanan yazi, resim ve dosyalar aranabilir listede. ⌘⇧V imlecin yaninda acar.
// Gizlilik: sifre yoneticilerinin isaretledigi (Concealed/Transient/AutoGenerated) icerik asla kaydedilmez.
// Gecmis userData/pano/gecmis.json'da; safeStorage varsa sifreli, yoksa yalniz kullanicinin okuyabildigi (0600) JSON.
const fs=require('fs'),crypto=require('crypto'),{fileURLToPath}=require('url'),power=require('./power');

const MAX=200,PIN_MAX=30,TEXT_MAX=100*1024,THUMB_MAX=64*1024,IMG_MAX=5*1024*1024,FILES_MAX=100,POLL_MS=700,POLL_MS_BATTERY=1500,PAUSE_MS=10*60*1000;
const SHORTCUT='CommandOrControl+Shift+V';
// nspasteboard.org isaretleri: sifre yoneticileri ve gecici/otomatik icerik bunlari koyar
const CONCEALED=['org.nspasteboard.ConcealedType','org.nspasteboard.TransientType','org.nspasteboard.AutoGeneratedType'];
const MAGIC=Buffer.from('CEMPANO1\n');                   // sifreli dosya basligi
const ID=/^[a-f0-9]{16}$/;
const sha=s=>crypto.createHash('sha1').update(s).digest('hex');
const newId=()=>crypto.randomBytes(8).toString('hex');
const num=v=>typeof v==='number'&&isFinite(v)?v:0;

// --- saf yardimcilar (testli) ----------------------------------------------
// Ucuz degisim imzasi: yazi + bicim listesi + (varsa) resim boyutu
function sigOf(s){return sha(JSON.stringify([s.formats||[],s.text||'',s.img||null]))}
// Gizli icerik: bicim listesinde, has() ile ya da ham veri olarak isaret varsa
function isConcealed(cb,formats){
  if((formats||[]).some(f=>CONCEALED.includes(f)))return true;
  for(const t of CONCEALED){
    try{if(typeof cb.has==='function'&&cb.has(t))return true}catch(e){}
    try{const b=cb.readBuffer&&cb.readBuffer(t);if(b&&b.length)return true}catch(e){}
  }
  return false;
}
// Yeni kayit ekle: ayni icerik varsa en uste tasinir (kopya olusmaz). Sinir asilinca en eski sabitlenmemis atilir.
function addItem(list,item,max=MAX){
  const i=list.findIndex(x=>x.key===item.key);
  if(i===0)return {list,changed:false,removed:[],kept:list[0]};
  const next=list.slice();let kept=item;
  if(i>0){kept={...next.splice(i,1)[0],at:item.at}}
  next.unshift(kept);
  const removed=[];
  for(let j=next.length-1;j>=0&&next.length>max;j--)if(!next[j].pin)removed.push(...next.splice(j,1));
  return {list:next,changed:true,removed,kept};
}
// Turkce buyuk/kucuk harf duyarsiz arama (I->ı, İ->i); her kelime gecmeli
const fold=s=>String(s||'').toLocaleLowerCase('tr-TR');
const hay=it=>it.type==='text'?it.text:it.type==='files'?(it.files||[]).join('\n'):'resim görsel ekran görüntüsü';
function search(list,q){
  const w=fold(q).trim().split(/\s+/).filter(Boolean);if(!w.length)return list;
  return list.filter(it=>{const h=fold(hay(it));return w.every(x=>h.includes(x))});
}
function ago(t,now=Date.now()){
  const s=Math.max(0,Math.round((now-t)/1000));if(s<45)return 'az önce';
  const m=Math.round(s/60);if(m<60)return m+' dk önce';
  const h=Math.round(m/60);if(h<24)return h+' sa önce';
  const d=Math.round(h/24);if(d===1)return 'dün';if(d<7)return d+' gün önce';
  return new Date(t).toLocaleDateString('tr-TR',{day:'numeric',month:'short'});
}
// Diskten okunan kaydi dogrula: bilinmeyen alan/tur atilir
function cleanItem(o){
  if(!o||typeof o!=='object'||!ID.test(o.id))return null;
  const b={id:o.id,type:o.type,at:num(o.at),pin:!!o.pin};
  if(o.type==='text'&&typeof o.text==='string'&&o.text.trim()&&Buffer.byteLength(o.text)<=TEXT_MAX)return {...b,text:o.text,key:'t:'+sha(o.text)};
  if(o.type==='image'&&typeof o.thumb==='string'&&/^data:image\/(png|jpeg);base64,/.test(o.thumb)&&o.thumb.length<=THUMB_MAX&&/^i:[a-f0-9]{40}$/.test(o.key))
    return {...b,thumb:o.thumb,w:num(o.w),h:num(o.h),key:o.key};
  if(o.type==='files'&&Array.isArray(o.files)){const f=o.files.filter(p=>typeof p==='string'&&p&&p.length<=4096).slice(0,FILES_MAX);
    if(f.length)return {...b,files:f,key:'f:'+sha(f.join('\0'))}}
  return null;
}
// Yuklenen listeyi duzenle: tekrarlar, sinir, en fazla 30 sabit
function normalize(items){
  const seen=new Set(),out=[];let pins=0;
  for(const x of (Array.isArray(items)?items:[]).map(cleanItem)){if(!x||seen.has(x.key))continue;seen.add(x.key);
    if(x.pin&&++pins>PIN_MAX)x.pin=false;out.push(x)}
  for(let j=out.length-1;j>=0&&out.length>MAX;j--)if(!out[j].pin)out.splice(j,1);
  return out;
}
// Disk bicimi: safeStorage varsa MAGIC + sifreli JSON, yoksa duz JSON
// Tam boy resimler de gecmis gibi sifrelenir (Anahtar Zinciri varsa): "CEMIMG1" + safeStorage(base64 PNG)
const IMG_MAGIC=Buffer.from('CEMIMG1');
function sealImg(png,ss){return ss?Buffer.concat([IMG_MAGIC,ss.encryptString(png.toString('base64'))]):png}
function openImg(buf,ss){if(buf.subarray(0,IMG_MAGIC.length).equals(IMG_MAGIC)){if(!ss)throw new Error('anahtar yok');
  return Buffer.from(ss.decryptString(buf.subarray(IMG_MAGIC.length)),'base64')}return buf}
function encodeStore(items,ss){
  const json=JSON.stringify({v:1,items});
  if(ss&&ss.isEncryptionAvailable())return Buffer.concat([MAGIC,ss.encryptString(json)]);
  return Buffer.from(json);
}
function decodeStore(buf,ss){
  let json;
  if(buf.subarray(0,MAGIC.length).equals(MAGIC)){
    if(!ss||!ss.isEncryptionAvailable())throw new Error('anahtar yok');
    json=ss.decryptString(buf.subarray(MAGIC.length));
  }else json=buf.toString('utf8');
  const o=JSON.parse(json);if(!o||o.v!==1||!Array.isArray(o.items))throw new Error('bicim');
  return normalize(o.items);
}
const xml=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const unxml=s=>s.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
const plist=paths=>'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'+
  '<plist version="1.0"><array>'+paths.map(p=>'<string>'+xml(p)+'</string>').join('')+'</array></plist>';
// Finder kopyasi: once tum dosyalar (NSFilenamesPboardType plist), yoksa tek dosya (public.file-url)
function readFiles(cb){
  try{let s=cb.read&&cb.read('NSFilenamesPboardType');if(!s&&cb.readBuffer){const b=cb.readBuffer('NSFilenamesPboardType');s=b&&b.length?b.toString('utf8'):''}
    if(s){const m=[...String(s).matchAll(/<string>([^<]*)<\/string>/g)].map(x=>unxml(x[1])).filter(p=>p.startsWith('/'));if(m.length)return m.slice(0,FILES_MAX)}}catch(e){}
  try{const u=cb.read&&cb.read('public.file-url');if(u&&String(u).startsWith('file://'))return [fileURLToPath(String(u).trim())]}catch(e){}
  return null;
}
// Kucuk onizleme: en uzun kenar 240 -> 48 piksel; 64 KB'a sigmazsa JPEG
function thumbOf(img){
  const {width:w,height:h}=img.getSize();
  const fit=W=>{const k=Math.min(1,W/Math.max(w,h,1));return k<1?img.resize({width:Math.max(1,Math.round(w*k)),height:Math.max(1,Math.round(h*k)),quality:'good'}):img};
  for(const W of [240,160,96,48]){const u=fit(W).toDataURL();if(u.length<=THUMB_MAX)return u}
  try{const u='data:image/jpeg;base64,'+fit(48).toJPEG(60).toString('base64');if(u.length<=THUMB_MAX)return u}catch(e){}
  return null;
}

function registerPano({ipcMain,app,BrowserWindow,path,clipboard,nativeImage,globalShortcut,screen,safeStorage,cfg,save,isOn=()=>true}){
  let list=[],on=false,loaded=false,readOnly=false,timer=null,lastSig=null,pausedUntil=0,scOk=null,win=null,saveT=null,dirty=false;
  const dir=()=>path.join(app.getPath('userData'),'pano'),file=()=>path.join(dir(),'gecmis.json'),imgDir=()=>path.join(dir(),'img');
  const imgPath=id=>path.join(imgDir(),id+'.png');
  const paused=()=>pausedUntil>Date.now();
  const ss=()=>{try{return safeStorage&&safeStorage.isEncryptionAvailable()?safeStorage:null}catch(e){return null}};

  // --- kalicilik ------------------------------------------------------------
  function load(){
    loaded=true;let buf;
    try{buf=fs.readFileSync(file())}catch(e){list=[];return}
    try{list=decodeStore(buf,ss())}
    catch(e){console.error('pano: gecmis okunamadi, bos baslatiliyor:',e.message);list=[];
      // Anahtar (Anahtar Zinciri) su an yoksa gecici bir sorundur: dosyaya ve resimlere dokunma, bu oturum diske yazma
      // (yoksa yeni dosya eskisini ezer ve bir sonraki acilista eski resimler sahipsiz sayilip silinirdi).
      if(buf.subarray(0,MAGIC.length).equals(MAGIC)&&!ss()){readOnly=true;return}
      // Anahtar var ama cozulemiyor (gercekten bozuk): zaman damgali yedege al, hicbir yedek digerini ezmesin
      try{fs.renameSync(file(),file()+'.bozuk-'+Date.now())}catch(_){}
      return}                                          // bu acilista resimlere dokunma
    // Listede olmayan resim dosyalarini temizle (bozuk yedek gecmis varsa onun resimleri de korunur)
    try{if(fs.readdirSync(dir()).some(f=>/^gecmis\.json\.bozuk/.test(f)))return;}catch(e){}
    try{const keep=new Set(list.filter(x=>x.type==='image').map(x=>x.id+'.png'));
      for(const f of fs.readdirSync(imgDir()))if(!keep.has(f))try{fs.unlinkSync(path.join(imgDir(),f))}catch(e){}}catch(e){}
  }
  function flush(){
    clearTimeout(saveT);saveT=null;if(!dirty||readOnly)return;dirty=false;
    try{fs.mkdirSync(dir(),{recursive:true,mode:0o700});
      const tmp=file()+'.'+process.pid+'.tmp';
      fs.writeFileSync(tmp,encodeStore(list,ss()),{mode:0o600});fs.renameSync(tmp,file())}
    catch(e){console.error('pano: kaydedilemedi:',e.message)}
  }
  const touch=()=>{dirty=true;clearTimeout(saveT);saveT=setTimeout(flush,1000);push()};
  const dropFiles=items=>{for(const x of items)if(x.type==='image')try{fs.unlinkSync(imgPath(x.id))}catch(e){}};

  // --- pano okuma -------------------------------------------------------------
  function snapshot(){
    let formats=[],text='',img=null;
    try{formats=clipboard.availableFormats()||[]}catch(e){}
    try{text=clipboard.readText()||''}catch(e){}
    if(formats.some(f=>/^image\//.test(f))){
      // Ucuz imza: ham PNG/TIFF bayt sayisi (buyuk resmi her 700 ms'de cozmemek icin); okunamazsa resmi coz
      let n=0;try{if(clipboard.readBuffer)n=(clipboard.readBuffer('public.png')||[]).length||(clipboard.readBuffer('public.tiff')||[]).length}catch(e){}
      if(n)img='b'+n;
      else try{const im=clipboard.readImage();if(im&&!im.isEmpty()){const s=im.getSize();img=s.width+'x'+s.height}}catch(e){}}
    return {formats,text,img};
  }
  function capture(snap){
    const now=Date.now(),files=readFiles(clipboard);
    if(files&&files.length)return {id:newId(),type:'files',files,at:now,pin:false,key:'f:'+sha(files.join('\0'))};
    if(snap.text&&snap.text.trim()){
      if(Buffer.byteLength(snap.text)>TEXT_MAX)return null;      // cok buyuk yazi kaydedilmez (yarim yapistirma olmasin)
      return {id:newId(),type:'text',text:snap.text,at:now,pin:false,key:'t:'+sha(snap.text)};
    }
    if(snap.img){
      const im=clipboard.readImage();if(!im||im.isEmpty())return null;
      const png=im.toPNG();if(!png||!png.length||png.length>IMG_MAX)return null;
      const key='i:'+sha(png),old=list.find(x=>x.key===key);
      if(old)return {...old,at:now};                              // ayni resim: dosyayi yeniden yazma
      const thumb=thumbOf(im);if(!thumb)return null;const s=im.getSize();
      return {id:newId(),type:'image',thumb,w:s.width,h:s.height,at:now,pin:false,key,_png:png};
    }
    return null;
  }
  function tick(){
    if(!on)return;
    const snap=snapshot(),sig=sigOf(snap);if(sig===lastSig)return;lastSig=sig;
    if(paused())return;
    if(isConcealed(clipboard,snap.formats))return;
    let item;try{item=capture(snap)}catch(e){console.error('pano:',e.message);return}
    if(!item)return;
    const png=item._png;delete item._png;
    if(png){try{fs.mkdirSync(imgDir(),{recursive:true,mode:0o700});fs.writeFileSync(imgPath(item.id),sealImg(png,ss()),{mode:0o600})}catch(e){console.error('pano: resim yazilamadi:',e.message);return}}
    const r=addItem(list,item);if(!r.changed)return;
    list=r.list;dropFiles(r.removed);touch();
  }

  // --- pencere ---------------------------------------------------------------
  const visible=()=>!!win&&!win.isDestroyed()&&win.isVisible();
  function view(){
    const now=Date.now(),ord=[...list.filter(x=>x.pin),...list.filter(x=>!x.pin)];
    return {items:ord.map(x=>({id:x.id,type:x.type,pin:x.pin,ago:ago(x.at,now),
        text:x.type==='text'?x.text.replace(/\s+/g,' ').trim().slice(0,400):undefined,
        lines:x.type==='text'?x.text.split('\n').length:undefined,
        thumb:x.thumb,w:x.w,h:x.h,files:x.files})),
      paused:paused()?Math.ceil((pausedUntil-now)/60000):0,shortcut:scOk!==false,pinMax:PIN_MAX,max:MAX};
  }
  function push(){if(visible())win.webContents.send('pano:data',view())}
  function makeWin(){
    win=new BrowserWindow({width:380,height:480,show:false,frame:false,resizable:false,movable:false,fullscreenable:false,skipTaskbar:true,
      alwaysOnTop:true,webPreferences:{preload:path.join(__dirname,'pano-preload.js'),sandbox:true}});
    win.loadFile(path.join(__dirname,'pano.html'));
    win.webContents.setWindowOpenHandler(()=>({action:'deny'}));win.webContents.on('will-navigate',e=>e.preventDefault());
    win.on('blur',()=>{if(!win.webContents.isDevToolsOpened())win.hide()});
    win.on('closed',()=>{win=null});
  }
  // Pencereyi imlecin yanina koy (ekrandan tasmasin)
  function open(){
    if(!isOn())return;if(!on)enable();if(!win)makeWin();
    const p=screen.getCursorScreenPoint(),d=screen.getDisplayNearestPoint(p).workArea,[w,h]=win.getSize();
    const x=Math.min(Math.max(p.x-Math.round(w/2),d.x+8),d.x+d.width-w-8);
    let y=p.y+12;if(y+h>d.y+d.height-8)y=Math.max(d.y+8,p.y-h-12);
    win.setPosition(Math.round(x),Math.round(y));
    try{app.focus&&app.focus({steal:true})}catch(e){}
    win.show();win.focus();win.webContents.send('pano:data',{...view(),shown:true});
  }
  function hide(){
    if(!visible())return;win.hide();
    // Mac'te onceki uygulamaya don ki hemen ⌘V yapilabilsin (uygulamanin baska acik penceresi yoksa)
    // Odak almayan pencereler (Borsa katmani, Neo baloncugu) engel sayilmaz; app.hide sonrasi yeniden (odaksiz) gosterilir
    try{if(process.platform==='darwin'&&app.hide){const others=(BrowserWindow.getAllWindows?BrowserWindow.getAllWindows():[]).filter(w=>w!==win&&!w.isDestroyed()&&w.isVisible());
      if(others.every(w=>w.isFocusable&&!w.isFocusable())){app.hide();setTimeout(()=>{for(const w of others)try{if(!w.isDestroyed())w.showInactive()}catch(_){}},150)}}}catch(e){}
  }
  function copyBack(id){
    const it=list.find(x=>x.id===id);if(!it)return {err:'Kayıt bulunamadı.'};
    try{
      if(it.type==='text')clipboard.writeText(it.text);
      else if(it.type==='image'){let im=null;try{im=nativeImage.createFromBuffer(openImg(fs.readFileSync(imgPath(it.id)),ss()))}catch(e){}if(!im||im.isEmpty())return {err:'Resim dosyası bulunamadı.'};clipboard.writeImage(im)}
      else{const f=it.files.filter(p=>{try{return fs.existsSync(p)}catch(e){return false}});if(!f.length)return {err:'Dosyalar artık yerinde değil.'};
        if(process.platform==='darwin')clipboard.writeBuffer('NSFilenamesPboardType',Buffer.from(plist(f)));else clipboard.writeText(f.join('\n'))}
    }catch(e){return {err:'Panoya yazılamadı.'}}
    lastSig=sigOf(snapshot());                                   // yokluyucu bunu yeni kayit saymasin
    const r=addItem(list,{...it,at:Date.now()});if(r.changed){list=r.list;touch()}
    hide();return {ok:true};
  }
  function remove(id){const i=list.findIndex(x=>x.id===id);if(i<0)return;dropFiles(list.splice(i,1));list=list.slice();touch()}
  function pin(id){const it=list.find(x=>x.id===id);if(!it)return null;
    if(!it.pin&&list.filter(x=>x.pin).length>=PIN_MAX)return {err:'En fazla '+PIN_MAX+' kayıt sabitlenebilir.'};
    list=list.map(x=>x===it?{...x,pin:!x.pin}:x);touch();return null}
  function clearAll(){list=[];dirty=true;flush();try{fs.unlinkSync(file()+'.bozuk')}catch(e){}   // okunamayan eski kopya da gitsin
    try{for(const f of fs.readdirSync(imgDir()))try{fs.unlinkSync(path.join(imgDir(),f))}catch(e){}}catch(e){}push()}

  // --- ac/kapat --------------------------------------------------------------
  // Kisayol bizde mi: isRegistered baska bir ozelligin kaydini da 'true' gosterir; sahiplik ayrica tutulur
  let mine=false;
  function arm(){try{if(mine&&globalShortcut.isRegistered&&globalShortcut.isRegistered(SHORTCUT))return scOk=true;mine=!!globalShortcut.register(SHORTCUT,open);scOk=mine}catch(e){scOk=mine=false}
    if(!scOk)console.warn('pano: '+SHORTCUT+' kısayolu kaydedilemedi.');return scOk}
  function enable(){
    if(on||!isOn())return;on=true;if(!loaded)load();
    lastSig=null;arm();schedule();tick();
  }
  // Yoklama hizi: prizde 0,7 sn, pilde 1,5 sn; ekran kilitli / Mac uykudayken hic (o arada kopyalama olmaz)
  function schedule(){clearInterval(timer);timer=null;if(!on||power.away())return;timer=setInterval(tick,power.state().battery?POLL_MS_BATTERY:POLL_MS)}
  function disable(){
    if(!on)return;on=false;clearInterval(timer);timer=null;
    if(mine)try{globalShortcut.unregister(SHORTCUT)}catch(e){}mine=false;scOk=null;pausedUntil=0;
    if(win&&!win.isDestroyed())win.close();win=null;flush();
  }
  // main.js globalShortcut.unregisterAll() cagirinca ⌘⇧V'yi geri al
  const rearm=()=>{if(on)arm()};

  const fromWin=e=>on&&!!win&&!win.isDestroyed()&&e.sender===win.webContents;
  const okId=id=>typeof id==='string'&&ID.test(id);
  ipcMain.handle('pano:state',e=>fromWin(e)?view():null);
  ipcMain.handle('pano:find',(e,q)=>fromWin(e)&&typeof q==='string'?search(list,q.slice(0,200)).map(x=>x.id):null);
  ipcMain.handle('pano:copy',(e,id)=>fromWin(e)&&okId(id)?copyBack(id):null);
  ipcMain.handle('pano:del',(e,id)=>{if(!fromWin(e)||!okId(id))return null;remove(id);return view()});
  ipcMain.handle('pano:pin',(e,id)=>{if(!fromWin(e)||!okId(id))return null;const r=pin(id);return {...view(),...(r||{})}});
  ipcMain.handle('pano:pause',e=>{if(!fromWin(e))return null;pausedUntil=paused()?0:Date.now()+PAUSE_MS;
    if(!pausedUntil)lastSig=sigOf(snapshot());                 // duraklatmadayken kopyalanan sonradan kaydedilmesin
    return view()});
  ipcMain.handle('pano:clear',e=>{if(!fromWin(e))return null;clearAll();return view()});
  ipcMain.handle('pano:hide',e=>{if(fromWin(e))hide()});
  app.whenReady().then(()=>{power.init();power.on(()=>{if(!on)return;schedule();if(!power.away())tick()});if(isOn())enable()});
  app.on('will-quit',()=>{flush();if(on)try{globalShortcut.unregister(SHORTCUT)}catch(e){}});
  const status=()=>{if(!on)return null;
    return [list.length+' kayıt',paused()?'duraklatıldı':null,scOk===false?'⌘⇧V kısayolu alınamadı':null].filter(Boolean).join(' · ')};
  // Neo (sesli asistan): ara, en iyi eslesmeyi panoya geri kopyala; metnin yalniz kisa onizlemesi doner
  function find(q){const r=search(list,String(q||'').slice(0,200));if(!r.length)return {error:'Pano geçmişinde bulunamadı.'};
    const it=r[0],c=copyBack(it.id);if(c&&c.err)return {error:c.err};
    return {ok:true,copied:{text:'yazı',image:'resim',files:'dosya'}[it.type]||it.type,preview:it.type==='text'?String(it.text).slice(0,120):'',matches:r.length}}
  return {enable,disable,open,status,rearm,tick,flush,hide,find};
}
module.exports={registerPano,sealImg,openImg,sigOf,isConcealed,addItem,search,ago,cleanItem,normalize,encodeStore,decodeStore,readFiles,thumbOf,plist,
  CONCEALED,MAX,PIN_MAX,TEXT_MAX,SHORTCUT};
